DROP TABLE IF EXISTS growth_records_backup_20260907;
CREATE TABLE growth_records_backup_20260907 AS SELECT * FROM growth_records;
DROP TABLE IF EXISTS notifications_backup_20260907;
CREATE TABLE notifications_backup_20260907 AS SELECT * FROM notifications;

-- ---------- 2. 清空测试数据（CASCADE 自动处理外键级联） ----------
